    Counts the number of pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.
    """
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        return 0

    t = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(t ** 0.5)
    for a in range(1, limit + 1):
        if t % a == 0:
            b = t // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest
    common divisor (GCD) and y0 as their least common multiple (LCM).

    Parameters:
    x0 (int): The required GCD of each pair.
    y0 (int): The required LCM of each pair.

    Returns:
    int: The total count of valid (P, Q) pairs.
    """
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        # If y0 is not a multiple of x0, no such pair exists
        return 0

    n = y0 // x0  # The product of the coprime factors a and b

    def gcd(a: int, b: int) -> int:
        """Euclidean algorithm for greatest common divisor."""
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(n ** 0.5)
    for a in range(1, limit + 1):
        if n % a == 0:
            b = n // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2  # (a,b) and (b,a)

    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ""

    # Map each value to its index in inorder for O(1) lookups
    idx_map = {ch: i for i, ch in enumerate(inorder)}

    def build(in_l: int, in_r: int, post_l: int, post_r: int) -> str:
        if in_l > in_r:
            return ""

        # Root is the last element in the current postorder segment
        root = postorder[post_r]
        root_idx = idx_map[root]

        # Number of nodes in the left subtree
        left_size = root_idx - in_l

        # Recursively construct left and right preorder strings
        left_pre = build(in_l, root_idx - 1, post_l, post_l + left_size - 1)
        right_pre = build(root_idx + 1, in_r, post_l + left_size, post_r - 1)

        return root + left_pre + right_pre

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals and
    returns the preorder traversal as a string.
    """
    if not inorder:
        return ''
    inorder_index = {char: idx for idx, char in enumerate(inorder)}

    def build(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end:
            return ''
        # The root is the last element in current postorder slice
        root = postorder[post_end]
        # Find root position in inorder
        in_root = inorder_index[root]
        left_len = in_root - in_start
