            if left_len > 0 else ''
        # Recurse on right subtree
        right = self_build(in_root + 1, in_end, post_start + left_len, post_end - 1) \
            if in_root < in_end else ''
        return root + left + right

    def self_build(in_s, in_e, post_s, post_e):
        return build(in_s, in_e, post_s, post_e)

    return self_build(0, len(inorder) - 1, 0, len(postorder) - 1)

