def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for i in range(n):
        ai = a[i]
        new_dp = [0] * (m + 1)
        # sliding window of prefix sums to compute in O(m)
        window_sum = 0
        for t in range(m + 1):
            window_sum += dp[t]
            if window_sum >= MOD:
                window_sum -= MOD
            if t - ai - 1 >= 0:
                window_sum -= dp[t - ai - 1]
                if window_sum < 0:
                    window_sum += MOD
            new_dp[t] = window_sum
        dp = new_dp
    return dp[m] % MOD

def minimum_students_to_leave(heights):
    if not heights:
        return 0
    n = len(heights)
    from bisect import bisect_left
    inc = [0] * n
    tails = []
    for i, h in enumerate(heights):
        pos = bisect_left(tails, h)
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
        inc[i] = pos + 1
    rev_heights = heights[::-1]
    dec_rev = [0] * n
    tails = []
    for i, h in enumerate(rev_heights):
        pos = bisect_left(tails, h)
        if pos == len(tails):
            tails.append(h)
        else:
            tails[pos] = h
        dec_rev[i] = pos + 1
    dec = [0] * n
    for i in range(n):
        dec[i] = dec_rev[n - 1 - i]
    max_len = 0
    for i in range(n):
        length = inc[i] + dec[i] - 1
        if length > max_len:
            max_len = length
    return n - max_len

